/**
 * Seasonal calendar: ADEME Impact CO2 «fruits et légumes de saison» -> src/features/seasonal/model/calendar.data.ts
 *
 * Source: https://impactco2.fr/api/v1/fruitsetlegumes?month=N (one call per month, unioned). The data
 * lives in https://github.com/incubateur-ademe/impactco2 (src/data/categories/fruitsetlegumes.ts),
 * MIT License, Copyright (c) 2022 Datagir. The notice is kept in the generated file.
 *
 * Usage (Node 22.18+ runs TypeScript directly), from the project root:
 *   node scripts/seasonal/build-calendar.ts
 * Then run `pnpm format` (the output is not Biome-formatted).
 */
import { writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = join(ROOT, 'src/features/seasonal/model/calendar.data.ts');
const API = 'https://impactco2.fr/api/v1/fruitsetlegumes';

interface ApiItem {
  name: string;
  slug: string;
  months: number[];
  ecv: number;
  category: string;
}

/** ADEME category labels -> our groups. */
const GROUPS: Record<string, string> = {
  fruits: 'fruits',
  légumes: 'legumes',
  herbes: 'herbes',
  'fruits à coque et graines oléagineuses': 'fruits_a_coque',
  'pommes de terre et autres tubercules': 'legumes',
  'pâtes, riz et céréales': 'legumes',
};

async function month(m: number): Promise<ApiItem[]> {
  const res = await fetch(`${API}?month=${m}`, { headers: { 'User-Agent': 'Cellier/1.0 (seasonal calendar)' } });
  if (!res.ok) throw new Error(`${API}?month=${m}: HTTP ${res.status}`);
  const body = (await res.json()) as { data: ApiItem[] };
  return body.data;
}

const bySlug = new Map<string, ApiItem>();
for (let m = 1; m <= 12; m++) for (const item of await month(m)) bySlug.set(item.slug, item);

const rows = [...bySlug.values()]
  .sort((a, b) => a.slug.localeCompare(b.slug))
  .map((i) => {
    const group = GROUPS[i.category];
    if (!group) throw new Error(`Unknown ADEME category «${i.category}» (${i.slug}); map it in GROUPS.`);
    const months = [...new Set(i.months)].sort((a, b) => a - b);
    return `  { slug: '${i.slug}', name: ${JSON.stringify(i.name)}, group: '${group}', months: [${months.join(', ')}], kgCo2e: ${Number(i.ecv.toFixed(3))} },`;
  });

const source = `/**
 * GENERATED by scripts/seasonal/build-calendar.ts — do not edit by hand.
 * Retrieved ${new Date().toISOString().slice(0, 10)} from ${API} (ADEME Impact CO2).
 *
 * Months (1 = January) are the season in mainland France; year-round entries are imports.
 * kgCo2e: life-cycle footprint in kg CO2e per kg.
 *
 * Data from https://github.com/incubateur-ademe/impactco2 — MIT License, Copyright (c) 2022 Datagir.
 * Permission is hereby granted, free of charge, to any person obtaining a copy of this software and
 * associated documentation files (the "Software"), to deal in the Software without restriction,
 * including without limitation the rights to use, copy, modify, merge, publish, distribute,
 * sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is
 * furnished to do so, subject to the following conditions: The above copyright notice and this
 * permission notice shall be included in all copies or substantial portions of the Software.
 * THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED.
 */
import type { SeasonalEntry } from './types';

export const ADEME_CALENDAR: readonly SeasonalEntry[] = [
${rows.join('\n')}
];
`;

writeFileSync(OUT, source);
console.log(`${rows.length} entries -> ${OUT}`);
